import React, { useState, useEffect } from 'react';

// Main component for the Jharkhand Academic Timetabling System (JATS)
const JharkhandAcademicSystem = () => {
  // --- STATE MANAGEMENT ---
  // Core state for UI
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentTab, setCurrentTab] = useState('dashboard');
  const [selectedStudentId, setSelectedStudentId] = useState(null);
  const [selectedClassForDateSheet, setSelectedClassForDateSheet] = useState(2); // Default to Grade 10-A

  // State for Gemini-powered features
  const [isSummaryLoading, setIsSummaryLoading] = useState(false);
  const [performanceSummary, setPerformanceSummary] = useState('');
  const [summaryError, setSummaryError] = useState('');
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [quizTopic, setQuizTopic] = useState('');
  const [generatedQuiz, setGeneratedQuiz] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [showQuizResults, setShowQuizResults] = useState(false);
  const [quizError, setQuizError] = useState('');

  // --- MOCK DATABASE & DATA ---
  const teachers = [
    { teacher_id: 1, first_name: 'Priya', last_name: 'Sharma', subject_id: 1 }, // English
    { teacher_id: 2, first_name: 'Rajesh', last_name: 'Kumar', subject_id: 3 }, // Mathematics
    { teacher_id: 3, first_name: 'Sunita', last_name: 'Gupta', subject_id: 7 }, // Chemistry
    { teacher_id: 4, first_name: 'Amit', last_name: 'Singh', subject_id: 6 }, // Physics
    { teacher_id: 5, first_name: 'Deepa', last_name: 'Verma', subject_id: 4 }, // Science
  ];

  const classes = [
    { class_id: 1, class_name: 'Grade 9 - Section A' }, { class_id: 2, class_name: 'Grade 10 - Section A' },
    { class_id: 3, class_name: 'Grade 10 - Section B' }, { class_id: 4, class_name: 'Grade 11 - Science' },
    { class_id: 5, class_name: 'Grade 11 - Commerce' }, { class_id: 6, class_name: 'Grade 11 - Arts' },
    { class_id: 7, class_name: 'Grade 12 - Science' }, { class_id: 8, class_name: 'Grade 12 - Commerce' },
    { class_id: 9, class_name: 'Grade 12 - Arts' }
  ];

  const students = [
    { student_id: 151, first_name: 'Akshita', last_name: 'Guleria', class_id: 1 },
    { student_id: 1, first_name: 'Arjun', last_name: 'Reddy', class_id: 1 }, { student_id: 2, first_name: 'Nikhil', last_name: 'Desai', class_id: 1 },
    { student_id: 3, first_name: 'Rohan', last_name: 'Joshi', class_id: 2 }, { student_id: 4, first_name: 'Meera', last_name: 'Singh', class_id: 2 },
    ...Array.from({ length: 146 }, (_, i) => {
        const firstNames = ['Aisha', 'Vihaan', 'Ishaan', 'Siya', 'Kabir', 'Anika', 'Reyansh', 'Kiara', 'Vivaan', 'Myra', 'Advik', 'Riya', 'Arnav', 'Saanvi', 'Dhruv'];
        const lastNames = ['Gupta', 'Sharma', 'Verma', 'Kumar', 'Singh', 'Malhotra', 'Kapoor', 'Mehta', 'Patel', 'Shah', 'Agarwal', 'Jain', 'Mishra', 'Pandey'];
        return { student_id: 5 + i, first_name: firstNames[Math.floor(Math.random() * firstNames.length)], last_name: lastNames[Math.floor(Math.random() * lastNames.length)], class_id: (i % 9) + 1 };
    })
  ];

  const subjects = [ { subject_id: 1, subject_name: 'English' }, { subject_id: 2, subject_name: 'Hindi' }, { subject_id: 3, subject_name: 'Mathematics' }, { subject_id: 4, subject_name: 'Science' }, { subject_id: 5, subject_name: 'Social Science' }, { subject_id: 6, subject_name: 'Physics' }, { subject_id: 7, subject_name: 'Chemistry' }, { subject_id: 8, subject_name: 'Computer Science' }, { subject_id: 9, subject_name: 'Accountancy' }, { subject_id: 10, subject_name: 'Business Studies' }, { subject_id: 11, subject_name: 'History' }, { subject_id: 12, subject_name: 'Geography' }, { subject_id: 13, subject_name: 'Political Science' }, { subject_id: 14, subject_name: 'Economics' }, { subject_id: 15, subject_name: 'Fine Arts' } ];
  const exams = [ { exam_id: 1, exam_name: 'Class Test - 1' }, { exam_id: 2, exam_name: 'Half Yearly Examination' }, { exam_id: 3, exam_name: 'Annual Examination' } ];
  
  const results = [
    // Existing Data
    { result_id: 1, student_id: 3, exam_id: 1, subject_id: 1, marks_obtained: 18.00, total_marks: 20.00 },
    { result_id: 2, student_id: 3, exam_id: 1, subject_id: 3, marks_obtained: 19.50, total_marks: 20.00 },
    { result_id: 3, student_id: 3, exam_id: 2, subject_id: 1, marks_obtained: 85.00, total_marks: 100.00 },
    { result_id: 4, student_id: 3, exam_id: 2, subject_id: 3, marks_obtained: 92.00, total_marks: 100.00 },
    { result_id: 5, student_id: 4, exam_id: 1, subject_id: 1, marks_obtained: 15.00, total_marks: 20.00 },
    { result_id: 6, student_id: 4, exam_id: 2, subject_id: 3, marks_obtained: 78.00, total_marks: 100.00 },
    { result_id: 7, student_id: 8, exam_id: 1, subject_id: 6, marks_obtained: 16.00, total_marks: 20.00 },
    { result_id: 8, student_id: 8, exam_id: 1, subject_id: 7, marks_obtained: 14.00, total_marks: 20.00 },
    { result_id: 9, student_id: 8, exam_id: 2, subject_id: 6, marks_obtained: 75.00, total_marks: 100.00 },
    { result_id: 10, student_id: 8, exam_id: 2, subject_id: 7, marks_obtained: 68.00, total_marks: 100.00 },
    { result_id: 11, student_id: 15, exam_id: 1, subject_id: 9, marks_obtained: 19.00, total_marks: 20.00 },
    { result_id: 12, student_id: 15, exam_id: 2, subject_id: 9, marks_obtained: 91.00, total_marks: 100.00 },
    { result_id: 13, student_id: 25, exam_id: 1, subject_id: 11, marks_obtained: 17.00, total_marks: 20.00 },
    { result_id: 14, student_id: 25, exam_id: 2, subject_id: 11, marks_obtained: 82.00, total_marks: 100.00 },
    
    // Newly Added Data
    { result_id: 15, student_id: 1, exam_id: 1, subject_id: 1, marks_obtained: 17.00, total_marks: 20.00 },
    { result_id: 16, student_id: 1, exam_id: 1, subject_id: 3, marks_obtained: 18.00, total_marks: 20.00 },
    { result_id: 17, student_id: 1, exam_id: 2, subject_id: 1, marks_obtained: 80.00, total_marks: 100.00 },
    { result_id: 18, student_id: 1, exam_id: 2, subject_id: 3, marks_obtained: 88.00, total_marks: 100.00 },
    { result_id: 19, student_id: 1, exam_id: 2, subject_id: 4, marks_obtained: 82.00, total_marks: 100.00 },
    { result_id: 20, student_id: 1, exam_id: 2, subject_id: 5, marks_obtained: 79.00, total_marks: 100.00 },

    { result_id: 21, student_id: 50, exam_id: 1, subject_id: 11, marks_obtained: 16.00, total_marks: 20.00 },
    { result_id: 22, student_id: 50, exam_id: 1, subject_id: 14, marks_obtained: 18.00, total_marks: 20.00 },
    { result_id: 23, student_id: 50, exam_id: 2, subject_id: 1, marks_obtained: 75.00, total_marks: 100.00 },
    { result_id: 24, student_id: 50, exam_id: 2, subject_id: 11, marks_obtained: 81.00, total_marks: 100.00 },
    { result_id: 25, student_id: 50, exam_id: 2, subject_id: 13, marks_obtained: 77.00, total_marks: 100.00 },
    { result_id: 26, student_id: 50, exam_id: 2, subject_id: 14, marks_obtained: 85.00, total_marks: 100.00 },

    { result_id: 27, student_id: 100, exam_id: 1, subject_id: 4, marks_obtained: 15.00, total_marks: 20.00 },
    { result_id: 28, student_id: 100, exam_id: 1, subject_id: 5, marks_obtained: 19.00, total_marks: 20.00 },
    { result_id: 29, student_id: 100, exam_id: 2, subject_id: 1, marks_obtained: 72.00, total_marks: 100.00 },
    { result_id: 30, student_id: 100, exam_id: 2, subject_id: 3, marks_obtained: 68.00, total_marks: 100.00 },
    { result_id: 31, student_id: 100, exam_id: 2, subject_id: 4, marks_obtained: 71.00, total_marks: 100.00 },
    { result_id: 32, student_id: 100, exam_id: 2, subject_id: 5, marks_obtained: 88.00, total_marks: 100.00 },

    // Akshita Guleria's Results
    { result_id: 33, student_id: 151, exam_id: 2, subject_id: 1, marks_obtained: 72.00, total_marks: 100.00 },
    { result_id: 34, student_id: 151, exam_id: 2, subject_id: 2, marks_obtained: 75.00, total_marks: 100.00 },
    { result_id: 35, student_id: 151, exam_id: 2, subject_id: 3, marks_obtained: 65.00, total_marks: 100.00 },
    { result_id: 36, student_id: 151, exam_id: 2, subject_id: 4, marks_obtained: 68.00, total_marks: 100.00 },
    { result_id: 37, student_id: 151, exam_id: 2, subject_id: 5, marks_obtained: 70.00, total_marks: 100.00 },
  ];

  const attendanceData = students.slice(0, 50).map((s, i) => ({ attendance_id: i + 1, student_id: s.student_id, class_id: s.class_id, attendance_date: '2025-09-18', status: Math.random() > 0.1 ? 'Present' : 'Absent' }));
  const initialLeaveRequests = [ { request_id: 1, student_id: 4, start_date: '2025-09-22', end_date: '2025-09-23', reason: 'Family function', status: 'Pending' }, { request_id: 2, student_id: 15, start_date: '2025-09-20', end_date: '2025-09-20', reason: 'Medical appointment', status: 'Pending' }, { request_id: 3, student_id: 33, start_date: '2025-09-16', end_date: '2025-09-16', reason: 'Not feeling well', status: 'Approved' }];

  const dateSheetData = {
    1: { classTest1: [ { subject: 'Science', date: '2025-09-29', time: '9:00 AM - 10:00 AM' }, { subject: 'Mathematics', date: '2025-09-30', time: '9:00 AM - 10:00 AM' }, ], halfYearly: [ { subject: 'English', date: '2025-11-15', time: '9:00 AM - 12:00 PM' }, { subject: 'Hindi', date: '2025-11-18', time: '9:00 AM - 12:00 PM' }, { subject: 'Mathematics', date: '2025-11-21', time: '9:00 AM - 12:00 PM' }, { subject: 'Science', date: '2025-11-24', time: '9:00 AM - 12:00 PM' }, { subject: 'Social Science', date: '2025-11-27', time: '9:00 AM - 12:00 PM' }, ] },
    2: { classTest1: [ { subject: 'Science', date: '2025-09-29', time: '9:00 AM - 10:00 AM' }, { subject: 'Mathematics', date: '2025-09-30', time: '9:00 AM - 10:00 AM' }, ], halfYearly: [ { subject: 'English', date: '2025-11-15', time: '9:00 AM - 12:00 PM' }, { subject: 'Hindi', date: '2025-11-18', time: '9:00 AM - 12:00 PM' }, { subject: 'Mathematics', date: '2025-11-21', time: '9:00 AM - 12:00 PM' }, { subject: 'Science', date: '2025-11-24', time: '9:00 AM - 12:00 PM' }, { subject: 'Social Science', date: '2025-11-27', time: '9:00 AM - 12:00 PM' }, ] },
    4: { classTest1: [ { subject: 'Physics', date: '2025-10-01', time: '9:00 AM - 10:00 AM' }, { subject: 'Chemistry', date: '2025-10-03', time: '9:00 AM - 10:00 AM' }, ], halfYearly: [ { subject: 'English', date: '2025-11-17', time: '9:00 AM - 12:00 PM' }, { subject: 'Physics', date: '2025-11-20', time: '9:00 AM - 12:00 PM' }, { subject: 'Chemistry', date: '2025-11-23', time: '9:00 AM - 12:00 PM' }, { subject: 'Mathematics', date: '2025-11-26', time: '9:00 AM - 12:00 PM' }, { subject: 'Computer Science', date: '2025-11-29', time: '9:00 AM - 11:00 AM' }, ] },
    8: { classTest1: [ { subject: 'Accountancy', date: '2025-10-01', time: '9:00 AM - 10:00 AM' }, { subject: 'Business Studies', date: '2025-10-03', time: '9:00 AM - 10:00 AM' }, ], halfYearly: [ { subject: 'English', date: '2025-11-17', time: '9:00 AM - 12:00 PM' }, { subject: 'Accountancy', date: '2025-11-20', time: '9:00 AM - 12:00 PM' }, { subject: 'Business Studies', date: '2025-11-23', time: '9:00 AM - 12:00 PM' }, { subject: 'Economics', date: '2025-11-26', time: '9:00 AM - 12:00 PM' }, ] }
  };

  const eventData = [
    { date: '2025-10-02', name: 'Gandhi Jayanti', type: 'holiday', color: 'bg-green-100 text-green-800' },
    { date: '2025-10-21', name: 'Diwali Celebration', type: 'event', color: 'bg-amber-100 text-amber-800' },
    { date: '2025-10-22', name: 'Diwali Break', type: 'holiday', color: 'bg-green-100 text-green-800' },
    { date: '2025-11-05', name: 'Science Exhibition', type: 'event', color: 'bg-cyan-100 text-cyan-800' },
    { date: '2025-11-14', name: 'Children\'s Day Fete', type: 'event', color: 'bg-pink-100 text-pink-800' },
    { date: '2025-11-28', name: 'Parent-Teacher Meeting', type: 'event', color: 'bg-blue-100 text-blue-800' },
    { date: '2025-12-20', name: 'Annual Sports Day', type: 'event', color: 'bg-orange-100 text-orange-800' },
    { date: '2025-12-24', name: 'Winter Break Starts', type: 'holiday', color: 'bg-green-100 text-green-800' },
    { date: '2026-01-26', name: 'Republic Day Parade', type: 'event', color: 'bg-indigo-100 text-indigo-800' },
  ];

  const [leaveRequests, setLeaveRequests] = useState(initialLeaveRequests);
  const [attendanceDate, setAttendanceDate] = useState('2025-09-18');

  // --- HELPER FUNCTIONS ---
  const getStudentFullName = (studentId) => { const s = students.find(s => s.student_id === studentId); return s ? `${s.first_name} ${s.last_name}` : 'Unknown'; };
  const getSubjectName = (subjectId) => { const s = subjects.find(s => s.subject_id === subjectId); return s ? s.subject_name : 'Unknown'; };
  const getExamName = (examId) => { const e = exams.find(e => e.exam_id === examId); return e ? e.exam_name : 'Unknown'; };
  const getClassName = (classId) => { const c = classes.find(cls => cls.class_id === classId); return c ? c.class_name : 'Unknown'; };
  
  // --- GEMINI API INTEGRATION ---
  const callGeminiAPI = async (payload, retries = 3, delay = 1000) => {
    const apiKey = ""; // API Key is not needed for this environment
    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-05-20:generateContent?key=${apiKey}`;
    for (let i = 0; i < retries; i++) {
        try {
            const response = await fetch(apiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
            if (!response.ok) { throw new Error(`API call failed: ${response.status}`); }
            const result = await response.json();
            const candidate = result.candidates?.[0];
            if (candidate?.content?.parts?.[0]?.text) { return candidate.content.parts[0].text; }
            else { throw new Error("Invalid API response"); }
        } catch (error) {
            if (i === retries - 1) { console.error("API call failed:", error); throw error; }
            await new Promise(res => setTimeout(res, delay * 2 ** i));
        }
    }
  };

  // --- EVENT HANDLERS ---
  const handleLogin = (e) => { e.preventDefault(); setIsLoggedIn(true); };
  const handleTabChange = (tab) => { setCurrentTab(tab); };
  const handleLeaveRequest = (reqId, status) => { setLeaveRequests(leaveRequests.map(r => r.request_id === reqId ? {...r, status} : r)); };
  const handleStudentSelect = (e) => { const id = Number(e.target.value); setSelectedStudentId(id); setPerformanceSummary(''); setSummaryError(''); };
  const handleQuizAnswerChange = (qIdx, ans) => { setUserAnswers(prev => ({...prev, [qIdx]: ans})); };
  const handleCheckQuizAnswers = () => { setShowQuizResults(true); };
  
  const handleGenerateSummary = async () => {
    if (!selectedStudentId) return;
    setIsSummaryLoading(true); setPerformanceSummary(''); setSummaryError('');
    const studentResults = results.filter(r => r.student_id === selectedStudentId);
    const studentName = getStudentFullName(selectedStudentId);
    if (studentResults.length === 0) { setSummaryError("No results found for this student."); setIsSummaryLoading(false); return; }
    const resultsText = studentResults.map(r => `- ${getSubjectName(r.subject_id)} in ${getExamName(r.exam_id)}: ${r.marks_obtained}/${r.total_marks}`).join('\n');
    const systemPrompt = "Act as a helpful and encouraging school teacher in India. Your tone should be positive and constructive.";
    const userQuery = `Write a concise, one-paragraph performance summary for ${studentName} for their parents. Based on these results, highlight one strength and suggest one area for improvement.\n\nResults:\n${resultsText}`;
    const payload = { contents: [{ parts: [{ text: userQuery }] }], systemInstruction: { parts: [{ text: systemPrompt }] }, };
    try { const summary = await callGeminiAPI(payload); setPerformanceSummary(summary); }
    catch (error) { setSummaryError("AI summary could not be generated."); }
    finally { setIsSummaryLoading(false); }
  };

  const handleGenerateQuiz = async () => {
      if (!quizTopic.trim()) { setQuizError("Please enter a topic."); return; }
      setIsQuizLoading(true); setGeneratedQuiz([]); setQuizError(''); setUserAnswers({}); setShowQuizResults(false);
      const userQuery = `Generate a 5-question multiple-choice quiz on "${quizTopic}". Provide 4 options per question, one correct.`;
      const quizSchema = { type: "ARRAY", items: { type: "OBJECT", properties: { question: { type: "STRING" }, options: { type: "ARRAY", items: { type: "STRING" }}, correct_answer: { type: "STRING" } }, required: ["question", "options", "correct_answer"] } };
      const payload = { contents: [{ parts: [{ text: userQuery }] }], generationConfig: { responseMimeType: "application/json", responseSchema: quizSchema } };
      try { const responseText = await callGeminiAPI(payload); const quizData = JSON.parse(responseText); setGeneratedQuiz(quizData); }
      catch (error) { setQuizError("Quiz could not be generated. Try another topic."); }
      finally { setIsQuizLoading(false); }
  };

  // RENDER LOGIC AND JSX
  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow-2xl p-8 w-full max-w-md">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-gray-800 mb-2">JATS Login</h1>
            <p className="text-gray-600">Jharkhand Academic Timetabling System</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Username</label>
              <input
                type="text"
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Enter your username"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <input
                type="password"
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Enter your password"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700 transition duration-200 font-medium"
            >
              Login
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <h1 className="text-2xl font-bold text-gray-900">JATS</h1>
              <span className="ml-2 text-sm text-gray-500">Academic Portal</span>
            </div>
            <button
              onClick={() => setIsLoggedIn(false)}
              className="text-gray-500 hover:text-gray-700 px-3 py-2 rounded-md text-sm font-medium"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      {/* Navigation */}
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex space-x-8">
            {[
              { id: 'dashboard', label: 'Dashboard' },
              { id: 'students', label: 'Students' },
              { id: 'results', label: 'Results' },
              { id: 'attendance', label: 'Attendance' },
              { id: 'leave', label: 'Leave Requests' },
              { id: 'datesheet', label: 'Date Sheet' },
              { id: 'calendar', label: 'Calendar' },
              { id: 'ai-tools', label: 'AI Tools' }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  currentTab === tab.id
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-6 sm:px-0">
          {currentTab === 'dashboard' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Dashboard</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">S</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Students</dt>
                          <dd className="text-lg font-medium text-gray-900">{students.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">C</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Classes</dt>
                          <dd className="text-lg font-medium text-gray-900">{classes.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-purple-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">T</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Teachers</dt>
                          <dd className="text-lg font-medium text-gray-900">{teachers.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-orange-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">E</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Exams</dt>
                          <dd className="text-lg font-medium text-gray-900">{exams.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {currentTab === 'students' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Students</h2>
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <ul className="divide-y divide-gray-200">
                  {students.slice(0, 20).map(student => (
                    <li key={student.student_id}>
                      <div className="px-4 py-4 sm:px-6">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center">
                            <div className="flex-shrink-0 h-10 w-10">
                              <div className="h-10 w-10 rounded-full bg-gray-300 flex items-center justify-center">
                                <span className="text-sm font-medium text-gray-700">
                                  {student.first_name[0]}{student.last_name[0]}
                                </span>
                              </div>
                            </div>
                            <div className="ml-4">
                              <div className="text-sm font-medium text-gray-900">
                                {student.first_name} {student.last_name}
                              </div>
                              <div className="text-sm text-gray-500">
                                {getClassName(student.class_id)}
                              </div>
                            </div>
                          </div>
                          <div className="text-sm text-gray-500">
                            ID: {student.student_id}
                          </div>
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {currentTab === 'ai-tools' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">AI-Powered Tools</h2>
              
              {/* Performance Summary */}
              <div className="bg-white shadow rounded-lg p-6">
                <h3 className="text-lg font-medium text-gray-900 mb-4">Student Performance Summary</h3>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Select Student</label>
                    <select
                      value={selectedStudentId || ''}
                      onChange={handleStudentSelect}
                      className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                    >
                      <option value="">Choose a student...</option>
                      {students.filter(s => results.some(r => r.student_id === s.student_id))
                        .map(student => (
                          <option key={student.student_id} value={student.student_id}>
                            {student.first_name} {student.last_name} - {getClassName(student.class_id)}
                          </option>
                        ))}
                    </select>
                  </div>
                  <button
                    onClick={handleGenerateSummary}
                    disabled={!selectedStudentId || isSummaryLoading}
                    className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isSummaryLoading ? 'Generating...' : 'Generate AI Summary'}
                  </button>
                  {summaryError && (
                    <div className="text-red-600 text-sm">{summaryError}</div>
                  )}
                  {performanceSummary && (
                    <div className="bg-blue-50 border border-blue-200 rounded-md p-4">
                      <h4 className="font-medium text-blue-900 mb-2">Performance Summary</h4>
                      <p className="text-blue-800">{performanceSummary}</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Quiz Generator */}
              <div className="bg-white shadow rounded-lg p-6">
                <h3 className="text-lg font-medium text-gray-900 mb-4">AI Quiz Generator</h3>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Topic</label>
                    <input
                      type="text"
                      value={quizTopic}
                      onChange={(e) => setQuizTopic(e.target.value)}
                      placeholder="Enter a topic (e.g., 'Indian History', 'Basic Mathematics')"
                      className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                    />
                  </div>
                  <button
                    onClick={handleGenerateQuiz}
                    disabled={isQuizLoading}
                    className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isQuizLoading ? 'Generating Quiz...' : 'Generate Quiz'}
                  </button>
                  {quizError && (
                    <div className="text-red-600 text-sm">{quizError}</div>
                  )}
                  {generatedQuiz.length > 0 && (
                    <div className="space-y-4">
                      {generatedQuiz.map((q, idx) => (
                        <div key={idx} className="bg-gray-50 border border-gray-200 rounded-md p-4">
                          <h4 className="font-medium text-gray-900 mb-3">Q{idx + 1}: {q.question}</h4>
                          <div className="space-y-2">
                            {q.options.map((option, optIdx) => (
                              <label key={optIdx} className="flex items-center">
                                <input
                                  type="radio"
                                  name={`question-${idx}`}
                                  value={option}
                                  checked={userAnswers[idx] === option}
                                  onChange={() => handleQuizAnswerChange(idx, option)}
                                  className="mr-2"
                                />
                                <span className="text-sm text-gray-700">{option}</span>
                              </label>
                            ))}
                          </div>
                          {showQuizResults && (
                            <div className="mt-3 text-sm">
                              <span className={`font-medium ${userAnswers[idx] === q.correct_answer ? 'text-green-600' : 'text-red-600'}`}>
                                {userAnswers[idx] === q.correct_answer ? '✓ Correct!' : '✗ Incorrect'}
                              </span>
                              {userAnswers[idx] !== q.correct_answer && (
                                <span className="text-gray-600 ml-2">Correct answer: {q.correct_answer}</span>
                              )}
                            </div>
                          )}
                        </div>
                      ))}
                      {!showQuizResults && (
                        <button
                          onClick={handleCheckQuizAnswers}
                          className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700"
                        >
                          Check Answers
                        </button>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Add other tab contents here */}
          {currentTab === 'results' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Student Results</h2>
              <div className="bg-white shadow overflow-hidden sm:rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Student
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Exam
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Subject
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Marks
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {results.slice(0, 20).map(result => (
                      <tr key={result.result_id}>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {getStudentFullName(result.student_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getExamName(result.exam_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getSubjectName(result.subject_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {result.marks_obtained}/{result.total_marks}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default JharkhandAcademicSystem;
